// ---- 1) What the SERVER sends (GET /v1/admin/overview) ----
// Hand-written from the Swagger example. Later you can replace these with the
// types generated by `openapi-typescript` (components["schemas"][...]).
export interface OverviewStatsDto {
  totalUsers: number;
  totalListings: number;
  newUsers30d: number;
  published: number;
}

export interface PendingListingDto {
  id: string;
  code: string;
  title: string;
  thumbnail?: string | null;
  owner: { id: string; name: string; role: string };
  propertyType: string; // "villa"
  transaction: string; // "rent" | "sale"
  area: string;
  price: number;
  currency: string; // "EGP"
  status: string; // "under_review"
  submittedAt: string; // ISO
}

export interface OverviewNotificationDto {
  id: string;
  type: string; // "listing_submitted"
  title: string;
  body: string;
  isRead: boolean;
  createdAt: string; // ISO
}

export interface AdminOverviewDto {
  stats: OverviewStatsDto;
  pendingListings: PendingListingDto[];
  recentNotifications: OverviewNotificationDto[];
  unreadNotifications: number;
}

export interface OverviewParams {
  pendingLimit: number;
  notificationsLimit: number;
}

// ---- 2) What the UI uses ----
export interface PendingListingVm {
  id: string;
  code: string;
  title: string;
  thumbnail?: string;
  ownerName: string;
  propertyType: string; // "Villa"
  transaction: string; // "Rent"
  area: string;
  priceLabel: string; // "75,000 EGP"
  submittedAt: string; // ISO (formatted by the component)
  statusLabel: string; // "Under Review"
}
